ALTER TABLE "inventory_patient_treatments" DROP CONSTRAINT "patient_treatment_cadence_valid";--> statement-breakpoint
ALTER TABLE "inventory_patient_treatments" ADD CONSTRAINT "patient_treatment_cadence_valid" CHECK (coalesce(("inventory_patient_treatments"."frequency_every" IS NULL AND "inventory_patient_treatments"."frequency_unit" IS NULL AND "inventory_patient_treatments"."frequency_every_days" IS NOT NULL) OR ("inventory_patient_treatments"."frequency_every" > 0 AND "inventory_patient_treatments"."frequency_unit" IN ('DAY','WEEK','MONTH') AND (("inventory_patient_treatments"."frequency_unit"='MONTH' AND "inventory_patient_treatments"."frequency_every_days" IS NULL) OR ("inventory_patient_treatments"."frequency_unit"='DAY' AND "inventory_patient_treatments"."frequency_every_days"="inventory_patient_treatments"."frequency_every") OR ("inventory_patient_treatments"."frequency_unit"='WEEK' AND "inventory_patient_treatments"."frequency_every_days"="inventory_patient_treatments"."frequency_every"*7))),false));